python3 << 'PYEOF'
import json

# Load all the registry definitions
with open('/tmp/ixp_invoiceixp_registry.json') as f:
    ixp_reg = json.load(f)
with open('/tmp/end_node.json') as f:
    end_reg = json.load(f)
with open('/tmp/script_node.json') as f:
    script_reg = json.load(f)

ixp_node = ixp_reg['Data']['Node']
end_node = end_reg['Data']['Node']
script_node = script_reg['Data']['Node']

# Also load the manual trigger definition from the existing flow
with open('/work/output/artifacts/skill-flow-ixp-routing/explicit/InvoiceProcessing/InvoiceProcessing/InvoiceProcessing.flow') as f:
    flow = json.load(f)

manual_trigger_defn = flow['definitions'][0]

ixp_defn = ixp_node
end_defn = end_node
script_defn = script_node

ixp_defaults = ixp_node['inputDefaults']
ixp_model_blob = ixp_defaults.get('model', {})
ixp_od = ixp_node['outputDefinition']

# Build the new flow
new_flow = {
    "id": flow['id'],
    "version": flow['version'],
    "name": flow['name'],
    "variables": {
        "globals": [
            {
                "id": "invoiceFile",
